type Vec3=[number,number,number];type Mat3=[Vec3,Vec3,Vec3];const B:Mat3=[[.8951,.2664,-.1614],[-.7502,1.7135,.0367],[.0389,-.0685,1.0296]],BI:Mat3=[[.9869929,-.1470543,.1599627],[.4323053,.5183603,.0492912],[-.0085287,.0400428,.9684867]];export const SUPPORTED_COLOR_SPACES={sRGB:{primaries:[[.64,.33],[.30,.60],[.15,.06]],white:'Illuminant D65'},'Display P3':{primaries:[[.68,.32],[.265,.69],[.15,.06]],white:'Illuminant D65'},UHDTV:{primaries:[[.708,.292],[.170,.797],[.13,.046]],white:'Illuminant D65'}} as const;export const SUPPORTED_WHITE_POINTS={'Illuminant D50':[.34567,.35850],'Illuminant D55':[.33242,.34743],'Illuminant D65':[.31272,.32903],'Illuminant D75':[.29902,.31485],'Illuminant E':[1/3,1/3]} as const;const mv=(m:Mat3,v:Vec3):Vec3=>[m[0][0]*v[0]+m[0][1]*v[1]+m[0][2]*v[2],m[1][0]*v[0]+m[1][1]*v[1]+m[1][2]*v[2],m[2][0]*v[0]+m[2][1]*v[1]+m[2][2]*v[2]];const mm=(a:Mat3,b:Mat3):Mat3=>[[a[0][0]*b[0][0]+a[0][1]*b[1][0]+a[0][2]*b[2][0],a[0][0]*b[0][1]+a[0][1]*b[1][1]+a[0][2]*b[2][1],a[0][0]*b[0][2]+a[0][1]*b[1][2]+a[0][2]*b[2][2]],[a[1][0]*b[0][0]+a[1][1]*b[1][0]+a[1][2]*b[2][0],a[1][0]*b[0][1]+a[1][1]*b[1][1]+a[1][2]*b[2][1],a[1][0]*b[0][2]+a[1][1]*b[1][2]+a[1][2]*b[2][2]],[a[2][0]*b[0][0]+a[2][1]*b[1][0]+a[2][2]*b[2][0],a[2][0]*b[0][1]+a[2][1]*b[1][1]+a[2][2]*b[2][1],a[2][0]*b[0][2]+a[2][1]*b[1][2]+a[2][2]*b[2][2]]];const dg=(v:Vec3):Mat3=>[[v[0],0,0],[0,v[1],0],[0,0,v[2]]];function inv(m:Mat3):Mat3{const[a,b,c]=m[0],[d,e,f]=m[1],[g,h,i]=m[2],A=e*i-f*h,B=-(d*i-f*g),C=d*h-e*g,D=-(b*i-c*h),E=a*i-c*g,F=-(a*h-b*g),G=b*f-c*e,H=-(a*f-c*d),I=a*e-b*d,k=1/(a*A+b*B+c*C);return[[A*k,D*k,G*k],[B*k,E*k,H*k],[C*k,F*k,I*k]]}const xy=([x,y]:readonly[number,number]):Vec3=>[x/y,1,(1-x-y)/y];export class ColorSystem{matrix:Mat3;invMatrix:Mat3;constructor(space:keyof typeof SUPPORTED_COLOR_SPACES='sRGB',adapt=''){const s=SUPPORTED_COLOR_SPACES[space],p=s.primaries,M:Mat3=[[p[0][0],p[1][0],p[2][0]],[p[0][1],p[1][1],p[2][1]],[1-p[0][0]-p[0][1],1-p[1][0]-p[1][1],1-p[2][0]-p[2][1]]],WP=xy(SUPPORTED_WHITE_POINTS[s.white]),S=mv(inv(M),WP);this.matrix=mm(M,dg(S));this.invMatrix=inv(this.matrix);if(adapt&&adapt!==s.white){const WPa=xy(SUPPORTED_WHITE_POINTS[adapt as keyof typeof SUPPORTED_WHITE_POINTS]),Bi=mv(B,WP),Ba=mv(B,WPa),A:Vec3=[Bi[0]/Ba[0],Bi[1]/Ba[1],Bi[2]/Ba[2]];this.matrix=mm(mm(mm(B,dg([1/A[0],1/A[1],1/A[2]])),BI),this.matrix);this.invMatrix=inv(this.matrix)}}xyzToRgb(v:Vec3){return mv(this.invMatrix,v)}rgbToXyz(v:Vec3){return mv(this.matrix,v)}}export const sRGBSystem=new ColorSystem('sRGB');export const applySRGBGamma=(v:number)=>{v=Math.max(0,v);return v<=.0031308?12.92*v:1.055*Math.pow(v,1/2.4)-.055};export function xyzToSRGB(xyz:Vec3):Vec3{let rgb=sRGBSystem.xyzToRgb(xyz),mn=Math.min(...rgb);if(mn<0)rgb=rgb.map(v=>v-mn)as Vec3;const mx=Math.max(...rgb,1e-12);return rgb.map(v=>Math.max(0,Math.min(1,applySRGBGamma(v/mx))))as Vec3}type Sample=[number,number];const parse=(t:string):Sample[]=>t.trim().split(/\r?\n/).map(l=>l.trim().split(/\s+/).slice(0,2).map(Number)as Sample).filter(v=>Number.isFinite(v[0])&&Number.isFinite(v[1]));let cmfPromise:Promise<{x:Sample[];y:Sample[];z:Sample[]}>|null=null;export function loadCIE1931CMF(){if(cmfPromise)return cmfPromise;cmfPromise=Promise.all((['x','y','z']as const).map(a=>fetch(`./assets/truecolor/CIE_1931_2deg.${a}.txt?v=1`).then(r=>r.text()).then(parse))).then(([x,y,z])=>({x,y,z}));return cmfPromise}const ip=(s:Sample[],nm:number)=>{if(nm<s[0][0]||nm>s[s.length-1][0])return 0;let l=0,h=s.length-1;while(h-l>1){const m=(l+h)>>1;if(s[m][0]<=nm)l=m;else h=m}const a=s[l],b=s[h],t=(nm-a[0])/(b[0]-a[0]||1);return a[1]+(b[1]-a[1])*t};export function parseSpectrumText(t:string,o:{wavelengthUnit?:'nm'|'um'|'angstrom'}={}):Sample[]{const f=o.wavelengthUnit==='um'?1000:(o.wavelengthUnit==='angstrom'?0.1:1);return parse(t).map(([w,v])=>[w*f,v])}export async function spectrumToXYZ(s:Sample[]):Promise<Vec3>{const cmf=await loadCIE1931CMF();let X=0,Y=0,Z=0;for(let i=0;i<s.length;i++){const[n,v]=s[i];if(n<360||n>830)continue;const step=i===0?(s[1]?.[0]-n||5):i===s.length-1?(n-s[i-1][0]||5):(s[i+1][0]-s[i-1][0])*.5;X+=v*ip(cmf.x,n)*step;Y+=v*ip(cmf.y,n)*step;Z+=v*ip(cmf.z,n)*step}const d=Math.max(1e-12,Y);return[X/d,1,Z/d]}export async function spectrumToSRGB(s:Sample[]){return xyzToSRGB(await spectrumToXYZ(s))}export const rgbToHex=(rgb:Vec3)=>Number.parseInt(rgb.map(v=>Math.round(Math.max(0,Math.min(1,v))*255).toString(16).padStart(2,'0')).join(''),16);
